diff --git a/src/gate.ts b/src/gate.ts
index 6b1e965..cbffaea 100644
--- a/src/gate.ts
+++ b/src/gate.ts
@@ -1,14 +1,58 @@
-export function normalizeGateNames(input: unknown): string[] {
-  void input;
-  throw new Error("not implemented");
+function sortedUnique(items: readonly string[]): string[] {
+  return [...new Set(items)].sort();
+}
+
+function checkRecords(value: unknown): Record<string, unknown>[] {
+  if (!Array.isArray(value)) {
+    return [];
+  }
+  return value.filter(
+    (item): item is Record<string, unknown> =>
+      typeof item === "object" && item !== null && !Array.isArray(item),
+  );
 }

-export function evaluateGate(input: unknown): unknown {
-  void input;
-  throw new Error("not implemented");
+function nameOf(rec: Record<string, unknown>): string {
+  return typeof rec.name === "string" ? rec.name : "";
+}
+export function evaluateGate(input: unknown): {
+  verdict: "pass" | "fail";
+  failed: string[];
+  unevidenced: string[];
+} {
+  if (typeof input !== "object" || input === null || Array.isArray(input)) {
+    return { verdict: "fail", failed: [], unevidenced: [] };
+  }
+  const rec = input as Record<string, unknown>;
+  const failed: string[] = [];
+  const unevidenced: string[] = [];
+  for (const check of checkRecords(rec.checks)) {
+    const name = nameOf(check);
+    if (check.passed !== true) {
+      failed.push(name);
+    } else if (check.evidenced !== true) {
+      unevidenced.push(name);
+    }
+  }
+  const verdict = failed.length === 0 && unevidenced.length === 0 ? "pass" : "fail";
+  return { verdict, failed: sortedUnique(failed), unevidenced: sortedUnique(unevidenced) };
+}
+
+export function normalizeGateNames(input: unknown): string[] {
+  if (!Array.isArray(input)) {
+    return [];
+  }
+  return sortedUnique(input.filter((item): item is string => typeof item === "string"));
 }

-export function gateTally(input: unknown): unknown {
-  void input;
-  throw new Error("not implemented");
+export function gateTally(input: unknown): { pass: number; fail: number } {
+  const tally = { pass: 0, fail: 0 };
+  for (const rec of checkRecords(input)) {
+    if (rec.verdict === "pass") {
+      tally.pass += 1;
+    } else if (rec.verdict === "fail") {
+      tally.fail += 1;
+    }
+  }
+  return tally;
 }

